/* BUILD12: attachment + SNU People vol70 + Haeahn 2022 photos. Dimensions remain estimates. */
function buildGatePlaza(B,scene,nav,height){
const V=(x,y,z)=>new B.Vector3(x,y,z),g=nav.gate,c=g.center,base=height(...c),a=Math.PI+.105,C=Math.cos(a),S=Math.sin(a),P=(x,y,z=0)=>V(c[0]+C*x-S*z,base+y,c[1]+S*x+C*z),groups=new Map(),gs=g.modelScale||1,GP=(x,y,z=0)=>P(x*gs,y*gs,z*gs);
const mat=(n,c)=>{const m=new B.StandardMaterial('gate12-'+n,scene);m.diffuseColor=B.Color3.FromHexString(c);m.specularColor=B.Color3.Black();return m},ivory=mat('ivory','#d7dcd9'),edge=mat('edge','#aebbb9'),dark=mat('inlay','#626c68'),metal=mat('metal','#536362'),soil=mat('soil','#73835e'),water=mat('water','#293e49');water.specularColor=new B.Color3(.3,.4,.42);water.specularPower=64;
function add(m,t){m.material=t;m.isPickable=false;if(!groups.has(t))groups.set(t,[]);groups.get(t).push(m);return m;}
function beam(n,from,to,w,d,t){if(n.startsWith('gate-')){w*=gs;d*=gs;}const v=to.subtract(from),m=B.MeshBuilder.CreateBox(n,{height:v.length(),width:w,depth:d},scene);m.position=from.add(to).scale(.5);m.rotationQuaternion=B.Quaternion.FromUnitVectorsToRef(B.Axis.Y,v.normalize(),new B.Quaternion());return add(m,t);}
function box(n,x,z,w,d,h,y,t){if(n.startsWith('gate-')){x*=gs;z*=gs;w*=gs;d*=gs;h*=gs;y*=gs;}const m=B.MeshBuilder.CreateBox(n,{width:w,depth:d,height:h},scene);m.position=P(x,y+h/2,z);m.rotation.y=-a;return add(m,t);}
function poly(n,ring,y,depth,t){const shape=ring.map(q=>P(q[0],0,q[1]));const m=B.MeshBuilder.ExtrudePolygon(n,{shape,depth,sideOrientation:B.Mesh.DOUBLESIDE},scene,earcut);m.position.y=base+y;return add(m,t);}
// Two steel skins and transverse webs: the oblique photograph shows open depth between them.
const outline=[[-9.6,.15],[-8.1,.15],[0,7.45],[8.35,.15],[9.55,.15],[9.55,11.25],[11.35,11.25],[11.35,12.35],[9.55,12.35],[9.55,13.25],[11.35,13.25],[11.35,14.35],[9.55,14.35],[9.55,16.6],[5.15,16.6],[5.15,15.45],[8.35,15.45],[8.35,1.95],[0,9.05]],tr=earcut(outline.flat());
for(const z of[-.98,.98]){const pos=[],ix=[],n=outline.length;for(const dz of[-.09,.09])for(const [x,y]of outline)pos.push(...GP(x,y,z+dz).asArray());for(let i=0;i<tr.length;i+=3)ix.push(tr[i],tr[i+2],tr[i+1],tr[i]+n,tr[i+1]+n,tr[i+2]+n);for(let i=0;i<n;i++){const j=(i+1)%n;ix.push(i,j,j+n,i,j+n,i+n);}const mesh=new B.Mesh('gate-steel-skin',scene),vd=new B.VertexData(),norm=[];B.VertexData.ComputeNormals(pos,ix,norm);Object.assign(vd,{positions:pos,indices:ix,normals:norm});vd.applyToMesh(mesh);mesh.material=ivory;mesh.isPickable=true;mesh.freezeWorldMatrix();}
for(const [x,y]of[[-8.7,.6],[-6,3],[-3,5.7],[0,8.2],[3,5.7],[6,3],[8.95,.6],[8.95,5],[8.95,10],[8.95,16],[5.7,16],[10.8,13.8],[10.8,11.8]])beam('gate-cross-web',GP(x,y,-1),GP(x,y,1),.6,.15,edge);
for(const side of[-1,1]){box('gate-foot',side*8.9,0,3.8,4.4,.15,0,ivory);for(const x of[-1.5,1.5])for(const z of[-1.9,1.9]){box('gate-bollard',side*8.9+x,z,.32,.32,.72,.15,ivory);const cap=B.MeshBuilder.CreateSphere('bollard-soft-cap',{diameter:.32*gs,segments:8},scene);cap.scaling.y=.3;cap.position=GP(side*8.9+x,.87,z);add(cap,ivory);}}
// Continuous low pale boundary; function deliberately not labelled bench or retaining wall.
const wall=g.plaza12.wallLocal;for(let i=1;i<wall.length;i++){const p=wall[i-1],q=wall[i];const dx=q[0]-p[0],dz=q[1]-p[1],len=Math.hypot(dx,dz),ox=-dz/len*.24,oz=dx/len*.24,ring=[[p[0]+ox,p[1]+oz],[q[0]+ox,q[1]+oz],[q[0]-ox,q[1]-oz],[p[0]-ox,p[1]-oz]];poly('plaza-white-boundary',ring,.95,.95,ivory);poly('plaza-boundary-cap',ring,1.0,.05,ivory);}
// BUILD44: water is an exclusive terrain partition; only low physical rims remain.
const ring=g.plaza12.basinLocal;for(const z of [30.1,36.2]){const h=5.5*(43-z)/19;beam('plaza-basin-divider',P(-h,.045,z),P(h,.045,z),.07,.10,edge);}
for(let i=0;i<3;i++){const p=ring[i],q=ring[(i+1)%3];beam('plaza-basin-rim',P(p[0],.04,p[1]),P(q[0],.04,q[1]),.075,.1,ivory);}
// Official full emblem, including laurels, book, pen and torch; monochrome stone inlay.
const tex=new B.DynamicTexture('official-emblem-inlay',{width:2048,height:2048},scene,true),em=mat('emblem','#ffffff');em.diffuseTexture=tex;tex.hasAlpha=true;em.useAlphaFromDiffuseTexture=true;em.transparencyMode=B.Material.MATERIAL_ALPHATEST;em.backFaceCulling=false;em.zOffset=-2;tex.anisotropicFilteringLevel=8;
const img=new Image();img.onload=()=>{const ctx=tex.getContext();ctx.clearRect(0,0,2048,2048);ctx.drawImage(img,0,0,2048,2048);const im=ctx.getImageData(0,0,2048,2048);for(let i=0;i<im.data.length;i+=4){const alpha=im.data[i+3]*(255-im.data[i])/255;im.data[i]=139;im.data[i+1]=139;im.data[i+2]=129;im.data[i+3]=alpha;}ctx.putImageData(im,0,0);tex.update();};img.src='snu-emblem.png';
const decal=B.MeshBuilder.CreateGround('plaza-official-emblem',{width:14,height:14.525},scene);decal.position=P(0,.025,13);decal.rotation.y=-a;decal.material=em;decal.isPickable=false;
// BUILD16: clip decorative bands and fixtures to the actual plaza, excluding road buffers.
function safe(x,z,margin=.6){const q=P(x,0,z);if(!WalkCore.inside(q.x,q.z,g.plazaOutline))return false;
 for(const road of nav.roads){for(let j=1;j<road.p.length;j++){const a=road.p[j-1],b=road.p[j],dx=b[0]-a[0],dz=b[1]-a[1],t=Math.max(0,Math.min(1,((q.x-a[0])*dx+(q.z-a[1])*dz)/(dx*dx+dz*dz||1)));if(Math.hypot(q.x-a[0]-t*dx,q.z-a[1]-t*dz)<(road.width||road.w||4)/2+margin)return false;}}return true;}
for(let z=-30;z<=64;z+=10){let start=null;for(let x=-16;x<=16.25;x+=.25){const ok=x<=16&&safe(x,z,.3);if(ok&&start===null)start=x;if(!ok&&start!==null){if(x-start>.25)beam('plaza-band',P(start,.018,z),P(x-.25,.018,z),.035,.08,dark);start=null;}}}
for(let i=0;i<40;i++){const z=-28+(i%10)*9,x=-13+Math.floor(i/10)*8;if(!safe(x,z,1)||(Math.abs(x)<6&&z>3&&z<44))continue;const m=B.MeshBuilder.CreateDisc('plaza-leaf-inlay',{radius:.5,tessellation:12,sideOrientation:B.Mesh.DOUBLESIDE},scene);m.position=P(x,.025,z);m.scaling=V(.7,1.7,1);m.rotation.x=Math.PI/2;m.rotation.y=a+(i%3)*.65;add(m,dark);}
const leaves=['#668052','#7d915e','#536f50','#8c9b68'].map((c,i)=>mat('leaf'+i,c)),bark=mat('bark','#93816b');
function tree(x,z,h,r,i){const q=P(x,0,z),y=height(q.x,q.z);beam('plaza-trunk',V(q.x,y,q.z),V(q.x,y+h*.78,q.z),h<8?.15:.5,.18,bark);for(let j=0;j<5;j++){const m=B.MeshBuilder.CreateSphere('plaza-canopy',{diameter:2,segments:10},scene),t=j*2.4+i;m.position=V(q.x+Math.sin(t)*r*.4,y+h*.68+j*h*.045,q.z+Math.cos(t)*r*.35);m.scaling=V(r*(.65+(j%3)*.09),h*(h<8?.24:.22),r*(.64+(j%2)*.13));add(m,leaves[(i+j)%4]);}}
for(let i=0;i<8;i++){const z=-29+i*12,x=-17.6+(z>20?(z-20)*.055:0);box('tree-grate',x,z,1.4,1.4,.025,.01,dark);tree(x,z,4.3+(i%3)*.6,.75+(i%2)*.18,i);}
for(let i=0;i<14;i++)tree(-26-(i%3)*5,-32+i*7,11+(i%4)*2,4+(i%3)*.7,i+10);
for(let i=0;i<5;i++)tree(34,18+i*13,10+(i%2)*2,2.3,i+30);
for(const x of[-15.8,14.5])for(let i=0;i<6;i++){const z=-27+i*17;if(!safe(x,z,1.2))continue;beam('plaza-lamp',P(x,0,z),P(x,5.8,z),.11,.11,metal);beam('plaza-lamp-arm',P(x-1,5.8,z),P(x+1,5.8,z),.11,.14,metal);box('plaza-lamp-light',x,z,1.8,.2,.05,5.75,ivory);}
// Follow the retained road centreline; paint does not widen or relocate the road.
const road=nav.roads.find(r=>r.id==='468202819'),yellow=mat('road-yellow','#d4af66');if(road&&!nav.ring33)for(let i=1;i<road.p.length;i++){const q=road.p[i-1],r=road.p[i];if(q[1]>866||r[1]<746)continue;const dx=r[0]-q[0],dz=r[1]-q[1],len=Math.hypot(dx,dz),nx=-dz/len,nz=dx/len;for(const off of[-.16,.16])beam('plaza-centreline',V(q[0]+nx*off,height(...q)+.03,q[1]+nz*off),V(r[0]+nx*off,height(...r)+.03,r[1]+nz*off),.025,.11,yellow);for(const off of[-3.2,3.2])for(let k=0;k<len;k+=7){const e=Math.min(len,k+3);beam('plaza-lane-dash',V(q[0]+dx*k/len+nx*off,height(...q)+.035,q[1]+dz*k/len+nz*off),V(q[0]+dx*e/len+nx*off,height(...r)+.035,q[1]+dz*e/len+nz*off),.025,.1,ivory);}}
for(const [m,list]of groups){const merged=B.Mesh.MergeMeshes(list,true,true);merged.material=m;merged.isPickable=false;merged.freezeWorldMatrix();}
}
